--------------------------------------------------------------------------------
-- C05b v2 · jumdae(LESP03D5114) — PKG_COM0000 배포 묶음 + AI 작업 흔적 (요약판 · 붙여넣기 한도 대응)
--   작성 2026-10-26 · 계정 SCM_MGR · SELECT 전용 · F5 실행 · 치환 변수 없음
--   v2 정정 (v1 오탐) :
--     · "[E2023~2025xxxx-000123]" = AS-IS 원본 소스의 변경요청 번호 → AI 마커 아님 (v1 이 오탐)
--     · "GENERATED BY DEFAULT AS IDENTITY" = Oracle 문법 → AI 표식 아님 (v1 이 오탐)
--     · AI 판정 = ① "Claude/Anthropic" 작업 주석 ② 이 프로젝트 AI 작업 마커 [E2026MMDD-영문꼬리표] (예: [E20260827-NLSDATE])
--   출력 순서 : 핵심(§A 배포 묶음 · §B PKG_COM0000 원문 머리) → 요약(§C 일자별 AI 흔적 건수) → §D 현재 접속
--------------------------------------------------------------------------------
SET DEFINE OFF
SET LINESIZE 300
SET PAGESIZE 500
SET TRIMSPOOL ON
SET TRIMOUT ON
COLUMN DB_NAME     FORMAT A14
COLUMN T_FIRST     FORMAT A19
COLUMN DAY         FORMAT A10
COLUMN DBUSERNAME  FORMAT A10
COLUMN ACTION_NAME FORMAT A20
COLUMN OBJ         FORMAT A40
COLUMN AI_EVIDENCE FORMAT A50
COLUMN HEAD        FORMAT A200
COLUMN SAMPLE_OBJ  FORMAT A60
COLUMN OSUSER      FORMAT A12
COLUMN MACHINE     FORMAT A20
COLUMN PROGRAM     FORMAT A40
COLUMN LOGON_TIME  FORMAT A19

PROMPT ================= §0 환경 =================
SELECT SYS_CONTEXT('USERENV','DB_NAME') AS DB_NAME, USER AS CONNECTED_AS
     , TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') AS RUN_AT FROM DUAL;

PROMPT ================= §A ⭐ PKG_COM0000 BODY 를 실은 배포 실행별 — 같은 실행(±2분)에 함께 생성·삭제된 객체 =================
PROMPT  jumdae 에게 "어느 배포 파일이었는지" 확인할 때 이 목록 전달 · AI_EVIDENCE = 그 객체 원문의 Claude 주석 / 프로젝트 AI 마커
SELECT TO_CHAR(B.EVENT_TIMESTAMP,'YYYY-MM-DD HH24:MI:SS') AS T_FIRST
     , B.DBUSERNAME, B.ACTION_NAME, B.OBJECT_NAME AS OBJ
     , DBMS_LOB.SUBSTR(REGEXP_SUBSTR(B.SQL_TEXT, '(CLAUDE|ANTHROPIC)[^' || CHR(10) || ']{0,40}|\[E2026\d{4}-[A-Z][A-Z0-9_-]*\]', 1, 1, 'i'), 50, 1) AS AI_EVIDENCE
  FROM UNIFIED_AUDIT_TRAIL B
 WHERE (UPPER(B.OS_USERNAME) LIKE '%JUMDAE%' OR UPPER(B.USERHOST) LIKE '%LESP03D5114%')
   AND B.OBJECT_NAME IS NOT NULL
   AND (B.ACTION_NAME LIKE 'CREATE%' OR B.ACTION_NAME LIKE 'DROP%')
   AND EXISTS (SELECT 1 FROM UNIFIED_AUDIT_TRAIL P
                WHERE (UPPER(P.OS_USERNAME) LIKE '%JUMDAE%' OR UPPER(P.USERHOST) LIKE '%LESP03D5114%')
                  AND UPPER(P.OBJECT_NAME) = 'PKG_COM0000'
                  AND P.ACTION_NAME = 'CREATE PACKAGE BODY'
                  AND P.EVENT_TIMESTAMP >= TIMESTAMP '2026-09-01 00:00:00'
                  AND B.EVENT_TIMESTAMP BETWEEN P.EVENT_TIMESTAMP - INTERVAL '2' MINUTE
                                            AND P.EVENT_TIMESTAMP + INTERVAL '2' MINUTE)
 ORDER BY B.EVENT_TIMESTAMP;

PROMPT ================= §B ⭐ PKG_COM0000 재배포 원문 머리 300자 + AI 흔적 유무 (전 기간) =================
SELECT TO_CHAR(A.EVENT_TIMESTAMP,'YYYY-MM-DD HH24:MI:SS') AS T_FIRST, A.ACTION_NAME
     , DBMS_LOB.SUBSTR(REGEXP_SUBSTR(A.SQL_TEXT, '(CLAUDE|ANTHROPIC)[^' || CHR(10) || ']{0,40}|\[E2026\d{4}-[A-Z][A-Z0-9_-]*\]', 1, 1, 'i'), 50, 1) AS AI_EVIDENCE
     , REPLACE(REPLACE(DBMS_LOB.SUBSTR(A.SQL_TEXT, 300, 1), CHR(10), ' '), CHR(13), ' ') AS HEAD
  FROM UNIFIED_AUDIT_TRAIL A
 WHERE (UPPER(A.OS_USERNAME) LIKE '%JUMDAE%' OR UPPER(A.USERHOST) LIKE '%LESP03D5114%')
   AND UPPER(A.OBJECT_NAME) = 'PKG_COM0000'
   AND A.ACTION_NAME IN ('CREATE PACKAGE','CREATE PACKAGE BODY')
 ORDER BY A.EVENT_TIMESTAMP;

PROMPT ================= §C 일자별 AI 흔적 요약 (원문 있는 DDL 기준 · 행 수 최소화) =================
PROMPT  CNT_CLAUDE = 원문에 Claude/Anthropic 주석 · CNT_AI_MARKER = [E2026MMDD-영문] 마커 · CNT_ASIS_REQNO = AS-IS 변경요청번호(참고, AI 아님)
SELECT TO_CHAR(A.EVENT_TIMESTAMP,'YYYY-MM-DD') AS DAY
     , COUNT(*) AS DDL_WITH_TEXT
     , SUM(CASE WHEN REGEXP_INSTR(A.SQL_TEXT, 'CLAUDE|ANTHROPIC', 1, 1, 0, 'i') > 0 THEN 1 ELSE 0 END) AS CNT_CLAUDE
     , SUM(CASE WHEN REGEXP_INSTR(A.SQL_TEXT, '\[E2026\d{4}-[A-Z]', 1, 1, 0, 'i') > 0 THEN 1 ELSE 0 END) AS CNT_AI_MARKER
     , SUM(CASE WHEN REGEXP_INSTR(A.SQL_TEXT, '\[E20\d{6}-\d{6}\]', 1, 1, 0) > 0 THEN 1 ELSE 0 END) AS CNT_ASIS_REQNO
     , SUBSTR(LISTAGG(CASE WHEN REGEXP_INSTR(A.SQL_TEXT, 'CLAUDE|ANTHROPIC|\[E2026\d{4}-[A-Z]', 1, 1, 0, 'i') > 0
                           THEN A.OBJECT_NAME END, ',' ON OVERFLOW TRUNCATE)
              WITHIN GROUP (ORDER BY A.EVENT_TIMESTAMP), 1, 60) AS SAMPLE_OBJ
  FROM UNIFIED_AUDIT_TRAIL A
 WHERE (UPPER(A.OS_USERNAME) LIKE '%JUMDAE%' OR UPPER(A.USERHOST) LIKE '%LESP03D5114%')
   AND A.SQL_TEXT IS NOT NULL
   AND (A.ACTION_NAME LIKE 'CREATE%' OR A.ACTION_NAME LIKE 'ALTER%')
 GROUP BY TO_CHAR(A.EVENT_TIMESTAMP,'YYYY-MM-DD')
 ORDER BY 1;

PROMPT ================= §D 현재 접속 중인 세션 =================
SELECT INST_ID, SID, SERIAL#, USERNAME AS DBUSERNAME, OSUSER, MACHINE, SUBSTR(PROGRAM,1,40) AS PROGRAM
     , TO_CHAR(LOGON_TIME,'YYYY-MM-DD HH24:MI:SS') AS LOGON_TIME
  FROM GV$SESSION
 WHERE UPPER(OSUSER) LIKE '%JUMDAE%' OR UPPER(MACHINE) LIKE '%LESP03D5114%'
 ORDER BY LOGON_TIME;

PROMPT ================= 끝 =================
